{
  "findings": [
    {
      "check_id": "CKV_AWS_20",
      "title": "S3 Bucket has an ACL defined which allows public READ access",
      "resource": "aws_s3_bucket.bucket_2",
      "severity": "CRITICAL",
      "explanation": "The bucket uses the deprecated 'acl' argument with a variable value. If this variable is set to 'public-read' or similar, it exposes data publicly. Modern best practice is to disable ACLs and use Bucket Policies for access control."
    },
    {
      "check_id": "CKV2_AWS_61",
      "title": "Ensure that an S3 bucket has a lifecycle configuration",
      "resource": "aws_s3_bucket.bucket_2",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket lacks a lifecycle configuration rule, which is recommended for managing object retention, expiration, and storage class transitions to optimize costs and compliance."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "bucket_2" {
  bucket = "roger-bucket-2"

  # CKV_AWS_20: Disable ACLs to prevent public exposure via legacy mechanism.
  # Access should be controlled via aws_s3_bucket_policy instead.
  acl = "private"

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        kms_master_key_id = aws_kms_key.my_key.arn
        sse_algorithm     = "aws:kms"
      }
    }
  }

  # CKV2_AWS_61: Add basic lifecycle configuration to manage object retention.
  lifecycle_rule {
    id      = "expire_old_objects"
    enabled = true

    expiration {
      days = 365
    }
  }
}",
  "fix_summary": "Hardened the S3 bucket by setting the ACL to 'private' to mitigate public read risks (CKV_AWS_20) and added a default lifecycle rule to expire objects after 365 days (CKV2_AWS_61). The existing KMS encryption configuration was preserved as it already satisfied encryption requirements."
}
